import {getPackageManagerDisplayName} from '../../types/packages'
import {BaseListItem} from '../BaseListView/BaseListItem'
import type {PackagePolicy} from '../../types/packages'

interface PackageExceptionsListItemProps {
  packageName: string
  packageManager: string
  spdxIDs: string[]
  isSelected: boolean
  hasCheckboxes: boolean
  onSelect: () => void
  onDelete?: (pkg: Pick<PackagePolicy, 'name' | 'package_manager'>) => void
}

export function PackageExceptionsListItem({
  packageName,
  packageManager,
  spdxIDs,
  isSelected,
  hasCheckboxes,
  onSelect,
  onDelete,
}: PackageExceptionsListItemProps) {
  const spdxExpression = spdxIDs.join(' AND ')
  const packageManagerName = getPackageManagerDisplayName(packageManager)
  const description = `${packageManagerName} • ${spdxExpression}`

  return (
    <BaseListItem
      title={packageName}
      description={description}
      isSelected={isSelected}
      onSelect={onSelect}
      onDelete={onDelete ? () => onDelete({name: packageName, package_manager: packageManager}) : undefined}
      hasCheckboxes={hasCheckboxes}
    />
  )
}

try{ PackageExceptionsListItem.displayName ||= 'PackageExceptionsListItem' } catch {}