import {createContext, useContext, type PropsWithChildren} from 'react'

export interface UserRepoPermissionsContextValue {
  hasRepoAdminPermissions: boolean
}

const DefaultUserRepoPermissionsContextValue: UserRepoPermissionsContextValue = {
  hasRepoAdminPermissions: false,
}

const UserRepoPermissionsContext = createContext(DefaultUserRepoPermissionsContextValue)

export function UserRepoPermissionsProvider({children, ...props}: PropsWithChildren<UserRepoPermissionsContextValue>) {
  return <UserRepoPermissionsContext.Provider value={props}>{children}</UserRepoPermissionsContext.Provider>
}

export function useUserRepoPermissions(): UserRepoPermissionsContextValue {
  const context = useContext(UserRepoPermissionsContext)
  return context
}

try{ UserRepoPermissionsContext.displayName ||= 'UserRepoPermissionsContext' } catch {}
try{ UserRepoPermissionsProvider.displayName ||= 'UserRepoPermissionsProvider' } catch {}