import type {PolicyLevel} from './policy-levels'

export type PackagePolicy = {
  name: string
  package_manager: string
  extra_allowed_spdx_ids: string[]
  level: PolicyLevel
}

const PackageManagerDisplayNames: Record<string, string> = {
  PACKAGE_MANAGER_RUBYGEMS: 'RubyGems',
  PACKAGE_MANAGER_NPM: 'npm',
  PACKAGE_MANAGER_PIP: 'pip',
  PACKAGE_MANAGER_MAVEN: 'Maven',
  PACKAGE_MANAGER_NUGET: 'NuGet',
  PACKAGE_MANAGER_COMPOSER: 'Composer',
  PACKAGE_MANAGER_GOMOD: 'Go',
  PACKAGE_MANAGER_RUST: 'Cargo',
  PACKAGE_MANAGER_ACTIONS: 'GitHub Actions',
  PACKAGE_MANAGER_PUB: 'Pub',
  PACKAGE_MANAGER_SWIFT: 'Swift',
}

export function getPackageManagerDisplayName(name: string): string {
  return PackageManagerDisplayNames[name] || 'Unknown'
}

export interface DeleteExceptionsFromEnterprisePolicyPayload {
  enterprise_slug: string
  packages: Array<Pick<PackagePolicy, 'name' | 'package_manager'>>
}

export interface DeleteExceptionsFromRepositoryPolicyPayload {
  repository_slug: string
  organization_slug: string
  packages: Array<Pick<PackagePolicy, 'name' | 'package_manager'>>
}
