import {useState, useMemo, useCallback, type ReactNode} from 'react'

import {BaseListFilter} from './BaseListFilter'

import {ListView} from '@github-ui/list-view'
import {ListViewMetadata} from '@github-ui/list-view/ListViewMetadata'
import {Blankslate} from '@primer/react/experimental'
import {Pagination, Button, Banner} from '@primer/react'
import {TrashIcon} from '@primer/octicons-react'

const PAGE_SIZE = 10

interface BaseListProps<T> {
  title: string
  items: T[]
  singleItemName: string
  pluralItemName: string
  zeroItemsHeading: string
  zeroItemsDescription: string
  zeroItemsIcon: ReactNode
  zeroItemsFilterHeading: string
  filterFunction: (item: T, filterText: string) => boolean
  renderItem: (item: T, index: number, isSelected: boolean, onSelect: () => void, itemKey: string) => ReactNode
  sortFunction?: (a: T, b: T) => number
  testId?: string
  renderFilter?: (props: {
    filterText: string
    onFilterChange: (e: React.ChangeEvent<HTMLInputElement>) => void
  }) => ReactNode
  getItemKey: (item: T) => string
  onBulkDelete?: (selectedItems: T[]) => void
  errorMessage?: {title: string; description: string}
}

export function BaseList<T>({
  title,
  items,
  singleItemName,
  pluralItemName,
  zeroItemsHeading,
  zeroItemsDescription,
  zeroItemsIcon,
  zeroItemsFilterHeading,
  filterFunction,
  renderItem,
  sortFunction,
  testId = 'base-list',
  renderFilter,
  getItemKey,
  onBulkDelete,
  errorMessage,
}: BaseListProps<T>) {
  const [filterText, setFilterText] = useState('')
  const [selectedItemIds, setSelectedItemIds] = useState<Set<string>>(() => new Set())
  const itemsTotalCount = items.length
  const [currentPage, setCurrentPage] = useState(1)

  // Handler for updating the filter text
  const handleFilterChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const newFilterText = e.target.value
      setFilterText(newFilterText)

      // Reset to page 1 when filter changes to ensure user sees results
      setCurrentPage(1)

      // Clear selections when filter text changes to avoid confusion about what's selected
      if (selectedItemIds.size > 0 && newFilterText.trim()) {
        setSelectedItemIds(new Set())
      }
    },
    [selectedItemIds.size],
  )

  // Updates items to filtered items when filter text changes
  const filteredItems = useMemo(() => {
    let result = items

    // Apply filtering if there's filter text
    if (filterText.trim()) {
      result = items.filter(item => filterFunction(item, filterText))
    }

    // Apply sorting if sortFunction is provided
    if (sortFunction) {
      result = [...result].sort(sortFunction)
    }

    return result
  }, [filterText, items, filterFunction, sortFunction])

  // Handler for individual item selection
  const handleItemSelect = useCallback((itemId: string) => {
    setSelectedItemIds(prev => {
      const newSelectedItems = new Set(prev)
      if (newSelectedItems.has(itemId)) {
        newSelectedItems.delete(itemId) // unselect
      } else {
        newSelectedItems.add(itemId)
      }
      return newSelectedItems
    })
  }, [])

  // Handler for select all
  const handleAllSelect = useCallback(
    (isAllSelected: boolean) => {
      if (isAllSelected) {
        const allIds = new Set(filteredItems.map(item => getItemKey(item)))
        setSelectedItemIds(allIds)
      } else {
        setSelectedItemIds(new Set())
      }
    },
    [filteredItems, getItemKey],
  )

  // Handler for delete action
  const handleBulkDelete = useCallback(() => {
    if (!onBulkDelete || selectedItemIds.size === 0) return

    const selectedItems = filteredItems.filter(item => selectedItemIds.has(getItemKey(item)))
    onBulkDelete(selectedItems)
    setSelectedItemIds(new Set()) // Clear selection after delete
  }, [filteredItems, selectedItemIds, onBulkDelete, getItemKey])

  const itemsCountLabel = `${filteredItems.length} ${filteredItems.length === 1 ? singleItemName : pluralItemName}`
  const itemsCountAnnouncement = `${itemsCountLabel} found${filterText.trim() ? ` matching "${filterText}"` : ''}`

  // Pagination
  const pageCount = Math.ceil(filteredItems.length / (1.0 * PAGE_SIZE)) || 1
  const pagedData = filteredItems.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE)

  const onPageChange = (e: React.MouseEvent, page: number) => {
    e.preventDefault() // Don't refresh the page
    window.scrollTo(0, 0)
    setSelectedItemIds(new Set()) // Clear selection
    setCurrentPage(page) // Update which page we're viewing
  }

  return (
    <>
      <div data-testid={testId}>
        {errorMessage ? (
          <Banner
            variant="critical"
            title={errorMessage.title}
            className="mb-3"
            hideTitle
            data-testid="bulk-delete-error-banner"
          >
            <Banner.Description>{errorMessage.description}</Banner.Description>
          </Banner>
        ) : null}

        {renderFilter ? (
          renderFilter({filterText, onFilterChange: handleFilterChange})
        ) : (
          <BaseListFilter filterText={filterText} onFilterChange={handleFilterChange} />
        )}

        <div className="border rounded-2">
          <ListView
            title={title}
            titleHeaderTag="h3"
            totalCount={itemsTotalCount}
            isSelectable={!!onBulkDelete}
            selectedCount={selectedItemIds.size}
            metadata={
              <ListViewMetadata
                title={itemsCountLabel}
                assistiveAnnouncement={itemsCountAnnouncement}
                onToggleSelectAll={handleAllSelect}
              >
                {onBulkDelete && selectedItemIds.size > 0 && (
                  <Button leadingVisual={TrashIcon} onClick={handleBulkDelete} aria-label="Delete selected items">
                    Delete
                  </Button>
                )}
              </ListViewMetadata>
            }
          >
            {itemsTotalCount === 0 && (
              <Blankslate>
                <Blankslate.Visual>{zeroItemsIcon}</Blankslate.Visual>
                <Blankslate.Heading>{zeroItemsHeading}</Blankslate.Heading>
                <Blankslate.Description>{zeroItemsDescription}</Blankslate.Description>
              </Blankslate>
            )}
            {itemsTotalCount > 0 && pagedData.length === 0 && (
              <Blankslate>
                <Blankslate.Heading>{zeroItemsFilterHeading}</Blankslate.Heading>
              </Blankslate>
            )}
            {itemsTotalCount > 0 &&
              pagedData.map((item, idx) => {
                const itemKey = getItemKey(item)
                const isSelected = selectedItemIds.has(itemKey)
                const onSelect = () => handleItemSelect(itemKey)

                return renderItem(item, idx, isSelected, onSelect, itemKey)
              })}
          </ListView>
        </div>
      </div>
      {filteredItems.length > PAGE_SIZE && (
        <Pagination
          pageCount={pageCount}
          currentPage={currentPage}
          onPageChange={onPageChange}
          aria-label="List pagination"
        />
      )}
    </>
  )
}

try{ BaseList.displayName ||= 'BaseList' } catch {}