import {useMutation, useQueryClient} from '@github-ui/react-query'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useRouteParams} from '@github-ui/react-core/future/use-route-params'

import {enterpriseLicensePolicyRoute} from '../routes/license-policy-route'
import {addLicensesToEnterprisePolicy} from '../services/licenses'
import type {AddLicensesToEnterprisePolicyPayload} from '../types/licenses'

// Mutation for adding licenses to the allowed licenses list of an enterprise policy
export function useAddAllowedLicensesToEnterpriseMutation() {
  const queryClient = useQueryClient()
  const {queryKey} = useRouteQuery(enterpriseLicensePolicyRoute, 'mainQuery')

  const {business} = useRouteParams(enterpriseLicensePolicyRoute)
  if (!business) {
    throw new Error('Business slug not found in route parameters')
  }

  return useMutation({
    mutationFn: ({spdxIds, context, onClose: _onClose}: {spdxIds: string[]; context: string; onClose?: () => void}) => {
      const payload: AddLicensesToEnterprisePolicyPayload = {
        enterprise_slug: business,
        spdx_ids: spdxIds,
        context,
      }
      // Call service which interacts with the OLC API
      return addLicensesToEnterprisePolicy(payload)
    },
    onSuccess: (data, variables) => {
      // Close dialog and refresh the license policy data
      if (variables.onClose) {
        variables.onClose()
      }
      queryClient.invalidateQueries({queryKey})
    },
  })
}
