import {reactFetchJSON} from '@github-ui/verified-fetch'
import type {
  AddLicensesToEnterprisePolicyPayload,
  DeleteLicensesFromEnterprisePolicyPayload,
  DeleteLicensesFromRepositoryPolicyPayload,
} from '../types/licenses'
import {getEnterpriseBaseRoute, getRepositoryBaseRoute} from '../routes/license-policy-route'

export async function addLicensesToEnterprisePolicy(payload: AddLicensesToEnterprisePolicyPayload) {
  const addToAllowedLicensesRoute = getEnterpriseAllowedLicensesRoute(payload.enterprise_slug)

  const response = await reactFetchJSON(addToAllowedLicensesRoute, {
    method: 'PUT',
    body: {spdx_ids: payload.spdx_ids, context: payload.context},
  })

  if (!response.ok) {
    const errorData = await response.json()
    throw new Error(errorData.error || response.statusText)
  }

  const data = await response.json()
  return data
}

export async function deleteLicensesFromEnterprisePolicy(payload: DeleteLicensesFromEnterprisePolicyPayload) {
  const deleteFromAllowedLicensesRoute = getEnterpriseAllowedLicensesRoute(payload.enterprise_slug)

  const response = await reactFetchJSON(deleteFromAllowedLicensesRoute, {
    method: 'DELETE',
    body: {spdx_ids: payload.spdx_ids, context: payload.context},
  })

  if (!response.ok) {
    const errorData = await response.json()
    throw new Error(errorData.error || response.statusText)
  }

  const data = await response.json()
  return data
}

export async function deleteLicensesFromRepositoryPolicy(payload: DeleteLicensesFromRepositoryPolicyPayload) {
  const deleteFromAllowedLicensesRoute = getRepositoryAllowedLicensesRoute(
    payload.organization_slug,
    payload.repository_slug,
  )

  const response = await reactFetchJSON(deleteFromAllowedLicensesRoute, {
    method: 'DELETE',
    body: {spdx_ids: payload.spdx_ids},
  })

  if (!response.ok) {
    const errorData = await response.json()
    throw new Error(errorData.error || response.statusText)
  }

  const data = await response.json()
  return data
}

function getEnterpriseAllowedLicensesRoute(enterprise_slug: string) {
  const baseRoute = getEnterpriseBaseRoute(enterprise_slug)
  return `${baseRoute}/licenses`
}

function getRepositoryAllowedLicensesRoute(organization_slug: string, repository_slug: string) {
  const baseRoute = getRepositoryBaseRoute(organization_slug, repository_slug)
  return `${baseRoute}/licenses`
}
