import {PageHeader} from '@primer/react'
import {BetaLabel} from '@github-ui/lifecycle-labels/beta'

interface LicensePolicyHeader {
  title: string
  description: string
  preview: boolean
}

export function LicensePolicyHeader({title, description, preview}: LicensePolicyHeader) {
  return (
    <>
      {/* Main page header with title and description */}
      <PageHeader hasBorder aria-label="License Policy">
        <PageHeader.TitleArea>
          <PageHeader.Title as="h1" className="h1-override-shared-component">
            {title}
          </PageHeader.Title>
          {preview && (
            <PageHeader.TrailingVisual>
              <BetaLabel>Preview</BetaLabel>
            </PageHeader.TrailingVisual>
          )}
        </PageHeader.TitleArea>
      </PageHeader>

      <PageHeader.Description className="color-fg-muted mb-4">{description}</PageHeader.Description>
    </>
  )
}

try{ LicensePolicyHeader.displayName ||= 'LicensePolicyHeader' } catch {}