import type {PackagePolicy} from '../../types/packages'
import {PackageExceptionsList} from '../PackageExceptions/PackageExceptionsList'
import {PackageExceptionsHeader} from '../PackageExceptions/PackageExceptionsHeader'

interface LicensePolicyPackageExceptionsProps {
  description: string
  packages: PackagePolicy[]
  deletePackageExceptionsMutation?: {
    mutate: (params: {packages: PackagePolicy[]}) => void
    error?: Error | null
    isError: boolean
    isPending: boolean
    reset: () => void
  }
}

export function LicensePolicyPackageExceptions({
  description,
  packages,
  deletePackageExceptionsMutation,
  ...props
}: LicensePolicyPackageExceptionsProps & React.HTMLAttributes<HTMLElement>) {
  return (
    <section {...props}>
      <PackageExceptionsHeader description={description} />

      <PackageExceptionsList packages={packages} deletePackageExceptionsMutation={deletePackageExceptionsMutation} />
    </section>
  )
}

try{ LicensePolicyPackageExceptions.displayName ||= 'LicensePolicyPackageExceptions' } catch {}