import {PageHeader, Button} from '@primer/react'
import {PlusIcon} from '@primer/octicons-react'
import type {ComponentProps} from 'react'

interface BaseListHeaderProps {
  title: string
  description: string
  addButtonLabel?: string
  onAddClick?: () => void
  addMutation?: {
    mutate: (params: {spdxIds: string[]; context: string}) => void
    error?: Error | null
  }
}

export function BaseListHeader({
  title,
  description,
  addButtonLabel = 'Add',
  onAddClick,
  addMutation,
  ...props
}: BaseListHeaderProps & Omit<ComponentProps<typeof PageHeader>, 'role' | 'children'>) {
  return (
    <>
      {/* Section header with add button */}
      <PageHeader role="group" {...props}>
        <PageHeader.TitleArea>
          <PageHeader.Title as="h2" className="h3-override-shared-component">
            {title}
          </PageHeader.Title>
        </PageHeader.TitleArea>
        <PageHeader.Actions>
          {onAddClick && (
            <Button leadingVisual={PlusIcon} onClick={onAddClick}>
              {addButtonLabel}
            </Button>
          )}
        </PageHeader.Actions>
      </PageHeader>

      <PageHeader.Description className="color-fg-muted mb-3">{description}</PageHeader.Description>
    </>
  )
}

try{ BaseListHeader.displayName ||= 'BaseListHeader' } catch {}