import {useMutation, useQueryClient} from '@github-ui/react-query'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useRouteParams} from '@github-ui/react-core/future/use-route-params'

import {enterpriseLicensePolicyRoute, repositoryLicensePolicyRoute} from '../routes/license-policy-route'
import {deleteExceptionsFromEnterprisePolicy, deleteExceptionsFromRepositoryPolicy} from '../services/packages'
import type {
  DeleteExceptionsFromEnterprisePolicyPayload,
  DeleteExceptionsFromRepositoryPolicyPayload,
  PackagePolicy,
} from '../types/packages'

// Mutation for deleting packages from the package exceptions list of an enterprise policy
export function useDeletePackageExceptionsFromEnterpriseMutation() {
  const queryClient = useQueryClient()
  const {queryKey} = useRouteQuery(enterpriseLicensePolicyRoute, 'mainQuery')

  const {business} = useRouteParams(enterpriseLicensePolicyRoute)
  if (!business) {
    throw new Error('Business slug not found in route parameters')
  }

  return useMutation({
    mutationFn: ({packages}: {packages: PackagePolicy[]}) => {
      const payload: DeleteExceptionsFromEnterprisePolicyPayload = {
        enterprise_slug: business,
        packages,
      }
      // Call service which interacts with the OLC API
      return deleteExceptionsFromEnterprisePolicy(payload)
    },
    onSuccess: () => {
      // Refresh the license policy data
      queryClient.invalidateQueries({queryKey})
    },
  })
}

// Mutation for deleting packages from the package exceptions list of a repository policy
export function useDeletePackageExceptionsFromRepositoryMutation() {
  const queryClient = useQueryClient()
  const {queryKey} = useRouteQuery(repositoryLicensePolicyRoute, 'mainQuery')

  const {organization, repository} = useRouteParams(repositoryLicensePolicyRoute)
  if (!organization) {
    throw new Error('Organization slug not found in route parameters')
  }
  if (!repository) {
    throw new Error('Repository slug not found in route parameters')
  }

  return useMutation({
    mutationFn: ({packages}: {packages: Array<Pick<PackagePolicy, 'name' | 'package_manager'>>}) => {
      const payload: DeleteExceptionsFromRepositoryPolicyPayload = {
        organization_slug: organization,
        repository_slug: repository,
        packages,
      }
      // Call service which interacts with the OLC API
      return deleteExceptionsFromRepositoryPolicy(payload)
    },
    onSuccess: () => {
      // Refresh the license policy data
      queryClient.invalidateQueries({queryKey})
    },
  })
}
